<?php
require __DIR__.'/payroll_corrections.php';
function job(string $action,array $input,?string $key=null,string $service='payroll'):array{global $owner,$clock;return ['actor'=>$owner,'clock'=>$clock,'action'=>$action,'input'=>$input,'key'=>$key??yk(),'service'=>$service];}
function race(array $jobs):array{$base=dirname(__DIR__,2).'/.local-setup/payroll-race-'.yk();$ps=[];foreach($jobs as $i=>$j){$p=proc_open([PHP_BINARY,__DIR__.'/payroll_worker.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fwrite($pipes[0],json_encode($j+['barrier'=>$base,'worker'=>$i]));fclose($pipes[0]);$ps[]=[$p,$pipes];}$until=microtime(true)+15;while(!is_file($base.'.ready0')||!is_file($base.'.ready1')){if(microtime(true)>$until)throw new RuntimeException('Worker barrier timeout');usleep(10000);}file_put_contents($base.'.go','go');$out=[];foreach($ps as [$p,$pipes]){$v=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0||$err)throw new RuntimeException('Worker failed: '.$err);$out[]=json_decode($v,true,512,JSON_THROW_ON_ERROR);}foreach(['.ready0','.ready1','.go'] as $suffix)unlink($base.$suffix);return $out;}
function wins(array $o):int{return count(array_filter($o,fn($v)=>$v['ok']));}
function approveInput(int $id):array{return yv($id)+['authorized'=>'1','reason'=>'Synthetic race approval'];}
function paymentInput(int $id,string $ref,string $amount='1125.00'):array{global $clock;return yv($id)+['amount'=>$amount,'reference'=>$ref,'paid_at'=>str_replace(' ','T',$clock),'verified'=>'1'];}
function readyPayroll():int{$id=ystart(ys(yu()));yprepare($id);return $id;}

function zready(bool $paid=false,bool $publish=false):int{global $owner,$s;$id=readyPayroll();yapprove($id);if($paid)ypay($id,'1125.00','RACE-ORIGINAL-'.yk());if($publish)yc($owner,'publish',yv($id)+['confirmed'=>'1','recipient_token'=>$s->detail($owner,$id)['recipient']['token']]);return $id;}
function zinput(int $id,array $more=[]):array{return $more+yv($id)+['type'=>'components','base'=>'1000.00','allowance'=>'150.00','overtime'=>'50.00','deductions'=>'25.00','employer'=>'75.00','reason'=>'PRIVATE concurrent source evidence checked','evidence_reference'=>'RACE-PROOF-'.yk(),'verified'=>'1'];}
$id=zready();$in=zinput($id);$key=yk();$out=race([job('correct',$in,$key),job('correct',$in,$key)]);ya(wins($out)===2&&$out[0]['result']['event_id']===$out[1]['result']['event_id']&&count($s->detail($owner,$id)['corrections'])===1,'identical simultaneous payroll correction posts once');
$id=zready();$in=zinput($id);$out=race([job('correct',$in),job('correct',$in)]);ya(wins($out)===1&&$s->detail($owner,$id)['approved']['net']===117500,'different concurrent correction keys cannot apply stale amounts twice');
$id=zready();$out=race([job('correct',zinput($id)),job('pay',paymentInput($id,'RACE-PAY-'.yk()))]);ya(wins($out)===1,'normal payout and component correction serialize against one source version');
$id=zready(true,true);zcorrect($id);ypay($id,'50.00','RACE-TOP-UP-'.yk());$c=$s->detail($owner,$id);$publish=yv($id)+['confirmed'=>'1','recipient_token'=>$c['recipient']['token']];$out=race([job('correct',zinput($id,['allowance'=>'200.00'])),job('publish',$publish)]);ya(wins($out)===1,'revised publication and another salary correction cannot use the same stale preview');
$id=zready(true,true);zcorrect($id);$c=$s->detail($owner,$id);$out=race([job('correct',zinput($id,['type'=>'payment','payment_id'=>(string)$c['payments'][0]['id'],'amount'=>'1100.00','recording_error'=>'1'])),job('pay',paymentInput($id,'RACE-COMPETING-TOP-UP-'.yk(),'50.00'))]);ya(wins($out)===1,'recorded-payment correction and actual top-up do not consume an old balance together');
echo "TOTAL $n payroll correction concurrency assertions passed.\n";
